            "ACME Corp": ["ACME Corporation", "ACME Inc.", "ACME"]
        },
        "preflight_allowlist": ["invoice", "purchase_order", "receipt", "payment"]
    }
    with open(_ALIASES_FILE, "w") as f:
        _json_aliases.dump(aliases, f, indent=2)

_atexit_refresh.register(_refresh_form_aliases)

if __name__ == "__main__":
    if len(sys.argv) != 4:
        print("Usage: fill_fillable_fields.py [input pdf] [field_values.json] [output pdf]")
